def numeroter_factures_existantes(apps, schema_editor):
    """Attribue FP-AAAA-MM-NNN aux factures prestataires déjà clôturées."""
    FacturePrestataire = apps.get_model('api', 'FacturePrestataire')
    mois_vus = {}
    for f in FacturePrestataire.objects.order_by('annee', 'mois', 'prestataire_libelle', 'id'):
        rang = mois_vus.get((f.annee, f.mois), 0) + 1
        mois_vus[(f.annee, f.mois)] = rang
        f.numero = f"FP-{f.annee}-{f.mois:02d}-{rang:03d}"
        f.save(update_fields=['numero'])


